package com.fitnutri.backend.records.workout;
import com.fitnutri.backend.common.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.submission.SubmissionService;
import java.math.BigDecimal;
import java.time.Clock;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import static com.fitnutri.backend.records.workout.ExerciseEntryInputs.*;
/** Root mutation is one owner transaction; a child cannot independently bypass the parent's version. */
@Service
public class WorkoutMutationService{
 private final RecordMutationGuard guard;private final JdbcTemplate jdbc;private final WorkoutSnapshotReader snapshots;private final WorkoutCorrectionPreviewService previews;private final ExerciseEntryV2Service creates;private final SubmissionService submissions;private final CanonicalV2Json canonical;private final ObjectMapper json;private final Clock clock;
 public WorkoutMutationService(RecordMutationGuard guard,JdbcTemplate jdbc,WorkoutSnapshotReader snapshots,WorkoutCorrectionPreviewService previews,ExerciseEntryV2Service creates,SubmissionService submissions,CanonicalV2Json canonical,ObjectMapper json,Clock clock){this.guard=guard;this.jdbc=jdbc;this.snapshots=snapshots;this.previews=previews;this.creates=creates;this.submissions=submissions;this.canonical=canonical;this.json=json;this.clock=clock;}
 @Transactional public WorkoutSnapshotReader.Root updateOwnedRoot(Long owner,String kind,long id,UpdateRequest request){guard.lockOwner(owner);if(request==null)throw BusinessException.invalid("request","Review a complete exercise correction.");guard.versionInput(request.expectedVersion());var root=lock(owner,kind,id);if(root.get("deleted_at")!=null)throw guard.missing();version(root,request.expectedVersion());ExerciseEntryInputValidator.validate(request.entry(),false);var incoming=periods(request.entry());var state=snapshots.state(owner,kind,id);var all=new ArrayList<Period>(incoming);all.addAll(periods(state.root().input()));creates.lockAuthority(all);if(kind.equals("workout"))jdbc.queryForList("SELECT id FROM exercise_record WHERE user_id=? AND workout_id=? ORDER BY id FOR UPDATE",owner,id);
  Map<UUID,Map<String,Object>> active=new HashMap<>();for(var p:state.periods())active.put((UUID)p.get("client_entry_id"),p);submissions.requireUnusedEntryIdentities(owner,incoming.stream().map(Period::clientEntryId).filter(uuid->!active.containsKey(uuid)).toList());var calculation=previews.calculateOwned(owner,kind,id,new CorrectionRequest(request.expectedVersion(),request.recordDate(),request.zone(),request.entry()));
  if(state.root().recordDate().equals(request.recordDate())&&canonical.canonical(normalise(state.root().input())).equals(canonical.canonical(normalise(request.entry()))))return state.root();
  if(!calculation.preview().fingerprint().equals(state.root().preview().fingerprint())){if(!ExerciseEntryInputValidator.hash(request.previewFingerprint()))throw BusinessException.invalid("previewFingerprint","Review the changed exercise estimate before confirming.");if(!calculation.preview().fingerprint().equals(request.previewFingerprint()))throw new ExerciseCalculationChangedV2Exception(calculation.preview());}
  var now=java.sql.Timestamp.from(clock.instant());if(kind.equals("workout"))jdbc.update("UPDATE workout_record SET title=?,recorded_date=?,updated_at=?,version=version+1 WHERE user_id=? AND id=?",((Workout)request.entry()).title()==null?"Gym workout":((Workout)request.entry()).title(),request.recordDate(),now,owner,id);
  var uuids=incoming.stream().map(Period::clientEntryId).toList();for(var p:active.entrySet())if(!uuids.contains(p.getKey()))jdbc.update("UPDATE exercise_record SET deleted_at=?,updated_at=?,version=version+1 WHERE user_id=? AND id=?",now,now,owner,p.getValue().get("id"));
  for(int position=0;position<calculation.periods().size();position++){var p=calculation.periods().get(position);var prior=active.get(p.input().clientEntryId());var values=new LinkedHashMap<String,Object>();values.put("exercise_option_id",p.option().getId());values.put("period_kind",p.input().periodKind());boolean sameOption=prior!=null&&Objects.equals(prior.get("exercise_option_id"),p.option().getId());values.put("exercise_type",sameOption?prior.get("exercise_type"):p.option().getDisplayName());values.put("option_name_snapshot",sameOption?prior.get("option_name_snapshot"):p.option().getDisplayName());values.put("recorded_date",java.sql.Date.valueOf(request.recordDate()));values.put("duration_minutes",p.input().durationMinutes());values.put("equipment_details",json.writeValueAsString(p.equipmentDetails()));values.put("period_position",kind.equals("workout")?position:null);var estimate=p.estimate();values.put("exercise_type_id",p.option().getReference()==null?null:p.option().getReference().getId());values.put("estimate_status",estimate==null?EstimateStatus.NO_APPLICABLE_REFERENCE.name():estimate.estimateStatus().name());values.put("estimated_kj",estimate==null?null:estimate.estimatedKj());values.put("weight_kg_used",estimate==null?null:estimate.weightKgUsed());values.put("weight_date_used",estimate==null||estimate.weightDateUsed()==null?null:java.sql.Date.valueOf(estimate.weightDateUsed()));values.put("met_used",estimate==null?null:estimate.metUsed());values.put("formula_version",estimate==null?null:estimate.formulaVersion());values.put("data_quality",prior==null?DataQuality.CURRENT.name():prior.get("data_quality"));long periodId;
   if(prior==null){values.put("user_id",owner);values.put("workout_id",id);values.put("client_entry_id",p.input().clientEntryId());values.put("source",root.get("source"));values.put("created_at",now);values.put("updated_at",now);values.put("recorded_at",now);periodId=jdbc.queryForObject("INSERT INTO exercise_record("+String.join(",",values.keySet())+") VALUES("+String.join(",",values.keySet().stream().map(k->k.equals("equipment_details")?"?::jsonb":"?").toList())+") RETURNING id",Long.class,values.values().toArray());}
   else{periodId=((Number)prior.get("id")).longValue();boolean dirty=values.entrySet().stream().anyMatch(e->!same(e.getKey(),prior.get(e.getKey()),e.getValue()));if(dirty||kind.equals("quick")){var args=new ArrayList<Object>(values.values());args.add(now);args.add(owner);args.add(periodId);jdbc.update("UPDATE exercise_record SET "+String.join(",",values.keySet().stream().map(k->k+"="+(k.equals("equipment_details")?"?::jsonb":"?")).toList())+",updated_at=?,version=version+1 WHERE user_id=? AND id=?",args.toArray());}}
   var oldMoves=state.movements().getOrDefault(periodId,List.of());if(!sameMovements(oldMoves,p.movements().stream().map(WorkoutEstimateService.SelectedMovement::input).toList()))replaceMovements(periodId,oldMoves,p.movements());
  }
  return snapshots.detailForReuse(owner,kind,id);
 }
 @Transactional public void softDeleteOwnedRoot(Long owner,String kind,long id,Long expectedVersion){guard.versionInput(expectedVersion);guard.lockOwner(owner);var root=lock(owner,kind,id);if(root.get("deleted_at")!=null)return;version(root,expectedVersion);var now=java.sql.Timestamp.from(clock.instant());if(kind.equals("workout"))jdbc.update("UPDATE exercise_record SET deleted_at=?,updated_at=?,version=version+1 WHERE user_id=? AND workout_id=? AND deleted_at IS NULL",now,now,owner,id);jdbc.update("UPDATE "+WorkoutSnapshotReader.table(kind)+" SET deleted_at=?,updated_at=?,version=version+1 WHERE user_id=? AND id=?",now,now,owner,id);}
 private Map<String,Object> lock(Long owner,String kind,long id){guard.id(id);var rows=jdbc.queryForList("SELECT * FROM "+WorkoutSnapshotReader.table(kind)+" WHERE user_id=? AND id=?"+(kind.equals("quick")?" AND workout_id IS NULL":"")+" FOR UPDATE",owner,id);if(rows.isEmpty())throw guard.missing();return rows.getFirst();}
 private static void version(Map<String,Object> row,Long expected){if(((Number)row.get("version")).longValue()!=expected)throw new BusinessException(HttpStatus.CONFLICT,"VERSION_CONFLICT","Reload and review the current exercise entry.");}
 static List<Period>periods(Entry input){return input instanceof Quick q?List.of(q.period()):((Workout)input).periods();}
 private static Entry normalise(Entry input){var ps=periods(input).stream().map(p->new Period(p.clientEntryId(),p.periodKind(),p.optionId(),p.durationMinutes(),ExerciseEntryInputValidator.validateEquipment(p.equipmentDetails()),p.movements(),null)).toList();if(input instanceof Quick q)return new Quick(q.clientEntryId(),ps.getFirst());var w=(Workout)input;return new Workout(w.clientEntryId(),w.title()==null?"Gym workout":w.title(),ps,w.originWorkoutId());}
 private boolean same(String key,Object a,Object b){if(key.equals("equipment_details"))return canonical.canonical(json.readTree(a.toString())).equals(canonical.canonical(json.readTree(b.toString())));if(a instanceof BigDecimal x&&b instanceof BigDecimal y)return x.compareTo(y)==0;return Objects.equals(a,b);}
 private boolean sameMovements(List<Map<String,Object>>prior,List<Movement>incoming){var old=prior.stream().map(m->new Movement(m.get("movement_catalogue_id").toString(),m.get("set_count")==null?null:((Number)m.get("set_count")).longValue(),m.get("repetitions")==null?null:((Number)m.get("repetitions")).longValue(),(BigDecimal)m.get("load_kg"))).toList();return canonical.canonical(old).equals(canonical.canonical(incoming));}
 private void replaceMovements(long periodId,List<Map<String,Object>>prior,List<WorkoutEstimateService.SelectedMovement>incoming){for(int i=0;i<incoming.size();i++){var m=incoming.get(i);if(i<prior.size()&&prior.get(i).get("movement_catalogue_id").equals(m.catalogue().getId()))jdbc.update("UPDATE workout_movement_log SET set_count=?,repetitions=?,load_kg=? WHERE id=?",m.input().setCount(),m.input().repetitions(),m.input().loadKg(),prior.get(i).get("id"));else{if(i<prior.size())jdbc.update("DELETE FROM workout_movement_log WHERE id=?",prior.get(i).get("id"));jdbc.update("INSERT INTO workout_movement_log(exercise_record_id,movement_catalogue_id,position,name_snapshot,load_basis_snapshot,set_count,repetitions,load_kg) VALUES(?,?,?,?,?,?,?,?)",periodId,m.catalogue().getId(),i,m.catalogue().getDisplayName(),m.catalogue().getLoadBasis(),m.input().setCount(),m.input().repetitions(),m.input().loadKg());}}for(int i=incoming.size();i<prior.size();i++)jdbc.update("DELETE FROM workout_movement_log WHERE id=?",prior.get(i).get("id"));}
}
